class Solution {
public:
 vector<int> recoverArray(vector<int>& nums){
  sort(nums.begin(),nums.end());int n=nums.size();
  for(int i=1;i<n;++i){int delta=nums[i]-nums[0];if(delta<=0 || delta%2)continue;
   map<int,int> cnt;for(int x:nums)++cnt[x];vector<int> out;bool ok=true;
   for(int x:nums){if(cnt[x]==0)continue;--cnt[x];
    if(cnt[x+delta]==0){ok=false;break;}
    --cnt[x+delta];out.push_back(x+delta/2);
   }
   if(ok && (int)out.size()*2==n)return out;
  }
  return {};
 }
};
